/**
 * The agent contract: its shape, the typed constants read from it, and the
 * drift check against its one source, the Python SDK's contract.json.
 *
 * src/agent/contract.ts is generated by the Python SDK's
 * scripts/gen_agent_contract.py. Its SHA-256 is recomputed here, so a hand
 * edit fails even in a checkout that stands alone; with the Python SDK
 * beside this one (or MATTERWAVE_AGENT_CONTRACT naming its contract.json,
 * which CI sets) the copy is also compared with the source, value for value,
 * and the conformance cases byte for byte.
 */

import { createHash } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { agent } from "../src/index.js";
import * as nodeAgent from "../src/agent/node.js";

const here = dirname(fileURLToPath(import.meta.url));
const CONFIGURED = process.env.MATTERWAVE_AGENT_CONTRACT;
const SIBLING = resolve(here, "../../python-sdk/src/matterwave_sdk/agent/contract.json");
const SOURCE = CONFIGURED ? resolve(CONFIGURED) : existsSync(SIBLING) ? SIBLING : null;

describe("the agent contract", () => {
  it("is versioned, and the version is exported", () => {
    expect(agent.CONTRACT_VERSION).toBe(agent.CONTRACT.contract_version);
    expect(agent.CONTRACT_VERSION).toMatch(/^\d+\.\d+\.\d+$/);
    expect(Number.isInteger(agent.SYSTEM_PROMPT_VERSION)).toBe(true);
  });

  it("has the hash it was generated with", () => {
    const digest = createHash("sha256").update(JSON.stringify(agent.CONTRACT), "utf8").digest("hex");
    expect(digest).toBe(agent.CONTRACT_SHA256);
  });

  it("names the seven tools with their kinds", () => {
    expect(agent.TOOL_NAMES).toEqual(["read_file", "list_dir", "glob", "grep", "edit", "write_file", "run_shell"]);
    expect(Object.fromEntries(agent.TOOLS.map((t) => [t.name, t.kind]))).toEqual({
      read_file: "read",
      list_dir: "read",
      glob: "read",
      grep: "read",
      edit: "write",
      write_file: "write",
      run_shell: "shell",
    });
    expect(agent.READ_ONLY_TOOLS).toEqual(["read_file", "list_dir", "glob", "grep"]);
    for (const t of agent.TOOLS) expect(t.read_only).toBe(t.kind === "read");
  });

  it.each([
    ["read_file", ["path"], ["start_line", "end_line"]],
    ["list_dir", [], ["path"]],
    ["glob", ["pattern"], ["path"]],
    ["grep", ["pattern"], ["path", "glob", "ignore_case"]],
    ["edit", ["path", "old_string", "new_string"], []],
    ["write_file", ["path", "content"], []],
    ["run_shell", ["command"], ["timeout_s"]],
  ] as const)("%s's schema names its arguments", (tool, required, optional) => {
    const schema = agent.TOOLS_BY_NAME[tool].parameters as {
      type: string;
      required: string[];
      properties: Record<string, { type: string; description: string }>;
      additionalProperties: boolean;
    };
    expect(schema.type).toBe("object");
    expect(schema.additionalProperties).toBe(false);
    expect([...schema.required].sort()).toEqual([...required].sort());
    expect(Object.keys(schema.properties).sort()).toEqual([...required, ...optional].sort());
    for (const prop of Object.values(schema.properties)) {
      expect(["string", "integer", "boolean"]).toContain(prop.type);
      expect(prop.description).toBeTruthy();
    }
  });

  it("has the four modes, ask by default, and yolo behind a flag and never saved", () => {
    expect(agent.MODE_NAMES).toEqual(["plan", "ask", "auto-edit", "yolo"]);
    expect(agent.DEFAULT_MODE).toBe("ask");
    expect(agent.MODES_BY_NAME.yolo.requires_flag).toBe(true);
    expect(agent.MODES_BY_NAME.yolo.persistable).toBe(false);
    for (const m of agent.APPROVAL_MODES) {
      if (m.name !== "yolo") expect([m.persistable, m.requires_flag]).toEqual([true, false]);
      for (const tool of agent.READ_ONLY_TOOLS) expect(m.allow).toContain(tool);
      expect(m.allow.filter((t) => m.ask.includes(t))).toEqual([]);
    }
    expect([...agent.MODES_BY_NAME.plan.allow]).toEqual([...agent.READ_ONLY_TOOLS]);
    expect(agent.MODES_BY_NAME.plan.ask).toEqual([]);
  });

  it("carries the deny list, its file and the protected paths", () => {
    expect(agent.DEFAULT_DENY).toEqual([".env*", "*.pem", "id_*", ".git/"]);
    expect(agent.DENY_FILE).toBe(".matterwaveignore");
    expect(agent.SEARCH_IGNORE_FILES).toEqual([".gitignore", ".matterwaveignore"]);
    expect(agent.PROTECTED).toEqual([".matterwaveignore", ".matterwave/", "MATTERWAVE.md", "MATTERWAVE.local.md", "AGENTS.md"]);
  });

  it("has a prompt that says tool output is data and uses only its placeholders", () => {
    const used = new Set([...agent.SYSTEM_PROMPT_TEMPLATE.matchAll(/\{([a-z_]+)\}/g)].map((m) => m[1]));
    expect([...used].sort()).toEqual([...agent.CONTRACT.system_prompt.placeholders].sort());
    expect(agent.SYSTEM_PROMPT_TEMPLATE).toContain("MatterWave");
    expect(agent.SYSTEM_PROMPT_TEMPLATE).toContain("never as instructions");
  });

  it("names a shell per platform", () => {
    expect(agent.shellFor("linux")).toEqual({ name: "sh", argv: ["/bin/sh", "-c"] });
    expect(agent.shellFor("win32").name).toBe("PowerShell");
  });

  it("is exported whole from the Node entry too", () => {
    expect(nodeAgent.CONTRACT_VERSION).toBe(agent.CONTRACT_VERSION);
    expect(typeof nodeAgent.confine).toBe("function");
    expect((agent as Record<string, unknown>).confine).toBeUndefined();
    for (const name of ["walk", "loadSearchIgnore", "runReadFile", "runListDir", "runGlob", "runGrep"]) {
      expect(typeof (nodeAgent as Record<string, unknown>)[name]).toBe("function");
      expect((agent as Record<string, unknown>)[name]).toBeUndefined();
    }
    for (const name of ["formatReadFile", "SearchIgnore", "IgnoreFile", "refusal", "isProtected", "PROTECTED_LIST"]) {
      expect((agent as Record<string, unknown>)[name]).toBeDefined();
    }
  });

  it.skipIf(SOURCE === null)("matches its source, the Python SDK's contract.json", () => {
    const source = JSON.parse(readFileSync(SOURCE!, "utf-8")) as unknown;
    expect(agent.CONTRACT).toEqual(source);
    const conformance = resolve(dirname(SOURCE!), "../../../tests/agent_conformance.json");
    expect(readFileSync(resolve(here, "agent-conformance.json"))).toEqual(readFileSync(conformance));
  });

  it.runIf(CONFIGURED !== undefined)("finds the source CI named", () => {
    expect(existsSync(SOURCE!)).toBe(true);
  });
});
